package com.ecole.gestion_scolaire.student.controller;
import com.ecole.gestion_scolaire.student.dto.*; import com.ecole.gestion_scolaire.student.service.StudentMedicalInfoService; import jakarta.validation.Valid; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/students/{studentId}/medical-info") public class StudentMedicalInfoController{private final StudentMedicalInfoService service;public StudentMedicalInfoController(StudentMedicalInfoService s){service=s;} @GetMapping @PreAuthorize("hasAuthority('INFO_MEDICALE_ELEVE_CONSULTER')") public StudentMedicalInfoResponse get(@PathVariable Long studentId){return service.findByStudent(studentId);} @PutMapping @PreAuthorize("hasAuthority('INFO_MEDICALE_ELEVE_GERER')") public StudentMedicalInfoResponse save(@PathVariable Long studentId,@Valid @RequestBody StudentMedicalInfoRequest r){return service.save(studentId,r);}}
